const root=document.querySelector('#prototype-content')
const heart='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 9c0 4-5 8-8 10C9 17 4 13 4 9a4 4 0 0 1 8-1 4 4 0 0 1 8 1Z"/></svg>'
const leaf='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M6 17C3 8 9 3 20 4c0 10-5 16-12 13M4 21 17 8"/></svg>'
const posts=[{id:'one',name:'Minh An',text:'Sáng nay mình tưới lại mấy chậu cây ngoài ban công. Có một chiếc lá mới vừa nhú lên. Một chuyện rất nhỏ thôi mà làm mình vui cả buổi.',image:true,topics:[0,1],count:2,reaction:null,saved:false,comments:['Mình cũng thích khoảnh khắc nhìn thấy một chiếc lá mới.','Góc ban công nghe bình yên quá.']},{id:'two',name:'Hà Linh',text:'Mình đang thử để điện thoại ở xa bàn ăn. Bữa tối hôm nay chậm hơn một chút, nhưng mình thấy dễ chịu. Các bạn có thói quen nhỏ nào để kết thúc ngày làm việc không?',image:false,topics:[3],count:2,reaction:null,saved:false,comments:[]},{id:'three',name:'Mây Nhẹ',text:'Hai khoảnh khắc nhỏ giúp mình chậm lại trong tuần. Một góc yên tĩnh và một khoảng trời rộng.',topics:[2,4],image:true,gallery:true,count:1,reaction:null,saved:false,comments:[]}]
let current='feed',failNext=false,draft='',profileName='Minh An',selected=[]
const photo='/images/progressive-relaxation-poster.jpg'
const landscape='/images/resource-mist-landscape.svg'
const labels=['Đồng hành','Mình cũng vậy','Cảm ơn bạn']
const topics=['Câu chuyện của tôi','Bước tiến nhỏ','Điều mình nhận ra','Hỏi cộng đồng','Chia sẻ trải nghiệm','Tài nguyên hữu ích']
const escapeText=value=>value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')
function card(post,detail=false){return `<article class="community-card" data-post="${post.id}"><header><span class="community-avatar">${leaf}</span><div><strong>${escapeText(post.name)}</strong><time>13 tháng 10 · 08:30</time></div></header><div class="community-card-topics">${renderTopics(post)}</div><p class="community-card-copy">${escapeText(post.text)}</p>${renderMedia(post)}<div class="social-reactions" role="group" aria-label="Gửi lời đồng hành">${labels.map((label,i)=>`<button data-reaction="${i}" aria-pressed="${post.reaction===i}">${i===1?leaf:heart}${label}</button>`).join('')}<span class="social-count" aria-live="polite">${post.count} lượt</span></div><div class="social-status" role="status"></div><div class="social-footer"><button data-comment>${post.comments.length} bình luận</button><button data-save aria-pressed="${post.saved}">${post.saved?'Đã lưu':'Lưu bài'}</button>${detail?'':'<button data-detail>Đọc bài viết →</button>'}</div></article>`}
function render(){if(current==='profile'){root.innerHTML=`<div class="social-panel"><h1>Danh tính cộng đồng</h1><p>Tên và hình đại diện riêng cho những chia sẻ của bạn.</p><section class="community-card"><div class="social-profile-preview"><span class="community-avatar">${leaf}</span><strong id="profile-preview">${escapeText(profileName)}</strong></div><form id="profile-form" novalidate><label>Tên hiển thị hoặc biệt danh<input id="profile-name" value="${escapeText(profileName)}" maxlength="80"></label><div class="social-profile-choices"><button type="button" aria-pressed="true">${leaf} Lá xanh</button><button type="button" aria-pressed="false">Bình minh</button><button type="button" aria-pressed="false">Gợn sóng</button></div><p class="social-meta">Danh tính này độc lập với hồ sơ cá nhân. Không hiển thị email của bạn.</p><div class="social-actions"><button class="social-primary">Lưu thay đổi</button></div><p class="social-status" role="status"></p></form></section></div>`;document.querySelector('#profile-name').oninput=e=>document.querySelector('#profile-preview').textContent=e.target.value;document.querySelector('#profile-form').onsubmit=e=>{e.preventDefault();profileName=document.querySelector('#profile-name').value.trim();document.querySelector('#profile-form .social-status').textContent=profileName?'Đã lưu danh tính cộng đồng':'Nhập tên hiển thị trước khi lưu.'};document.querySelectorAll('.social-profile-choices button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.social-profile-choices button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)))});return}
const detail=posts.find(post=>current===post.id)
if(detail){root.innerHTML=`<div class="social-panel"><button id="back-feed">← Trở về bảng tin</button>${card(detail,true)}<section class="community-card" style="margin-top:16px"><h2>Bình luận hỗ trợ</h2><label for="comment-draft">Lời chia sẻ của bạn</label><textarea id="comment-draft" rows="3"></textarea><div class="social-actions"><button class="social-primary" id="send-comment">Gửi bình luận</button></div><div id="comment-list">${detail.comments.map(text=>`<div class="social-comment"><strong>Thành viên cộng đồng</strong><p>${escapeText(text)}</p></div>`).join('')}</div></section></div>`;document.querySelector('#back-feed').onclick=()=>navigate('feed');document.querySelector('#send-comment').onclick=()=>{const input=document.querySelector('#comment-draft');if(input.value.trim()){detail.comments.push(input.value.trim());render()}};wireCards();return}
const saved=current==='saved';root.innerHTML=`<div class="community-page"><div class="community-feed-intro"><header class="community-hero"><h1>${saved?'Bài viết đã lưu':'Cộng đồng MentalBridge'}</h1><p>${saved?'Những câu chuyện bạn muốn giữ bên mình. Chỉ bạn thấy danh sách này.':'Cùng chia sẻ những điều nhỏ bé trong ngày.'}</p></header>${saved?'':`<section class="community-card social-launcher" style="display:flex;align-items:center;gap:16px"><span class="community-avatar">${leaf}</span><div style="flex:1"><strong>Bạn muốn chia sẻ điều gì?</strong><p class="social-meta">Một suy nghĩ, một câu chuyện, một bước tiến nhỏ.</p></div><button id="compose" class="social-primary" style="min-height:44px;padding:0 16px;border-radius:12px">${draft?'Viết tiếp':'Viết bài'}</button></section>`}</div>${saved?'':`<aside class="community-topic-dock"><details ${innerWidth>900?'open':''}><summary style="min-height:44px;font-weight:600">Khám phá theo chủ đề</summary><p class="social-meta">Chọn tối đa 3</p><div class="community-topics"><button data-topic="all" aria-pressed="${!selected.length}">Tất cả</button>${topics.map((topic,i)=>`<button data-topic="${i}" aria-pressed="${selected.includes(i)}" class="${selected.includes(i)?'is-active':''}">${topic}</button>`).join('')}</div></details></aside>`}<div class="community-feed-content"><section class="community-feed">${posts.filter(post=>saved?post.saved:!selected.length||selected.some(topic=>(post.topics??[0]).includes(topic))).map(post=>card(post)).join('')||emptyState(saved)}</section></div></div>`;document.querySelector('#compose')?.addEventListener('click',compose);document.querySelectorAll('[data-topic]').forEach(button=>button.onclick=()=>{const value=button.dataset.topic;if(value==='all')selected=[];else{const n=Number(value);selected=selected.includes(n)?selected.filter(i=>i!==n):selected.length<3?[...selected,n]:selected}const expanded=document.querySelector(".community-topic-dock details")?.open;render();if(expanded)document.querySelector(".community-topic-dock details").open=true;document.querySelector(`[data-topic="${value}"]`)?.focus()});wireCards()}
function wireCards(){document.querySelectorAll('[data-post]').forEach(article=>{const post=posts.find(p=>p.id===article.dataset.post);article.querySelectorAll('[data-reaction]').forEach(button=>button.onclick=async()=>{const buttons=article.querySelectorAll('[data-reaction], [data-save]');buttons.forEach(item=>item.disabled=true);article.querySelector('.social-status').setAttribute('role','status');article.querySelectorAll('[data-pulse]').forEach(item=>delete item.dataset.pulse);article.querySelector('.social-status').textContent='Đang gửi…';await new Promise(resolve=>setTimeout(resolve,650));if(failNext){failNext=false;document.querySelector('#simulate-error').textContent='Thử lỗi thao tác kế tiếp';article.querySelector('.social-status').setAttribute('role','alert');article.querySelector('.social-status').textContent='Chưa thể gửi lời đồng hành. Bạn có thể thử lại.'}else{const next=Number(button.dataset.reaction),previous=post.reaction;post.reaction=previous===next?null:next;post.count+=previous===null?1:post.reaction===null?-1:0;article.querySelector('.social-count').textContent=`${post.count} lượt`;article.querySelectorAll('[data-reaction]').forEach(item=>item.setAttribute('aria-pressed',String(post.reaction===Number(item.dataset.reaction))));if(post.reaction!==null&&!matchMedia('(prefers-reduced-motion: reduce)').matches){button.dataset.pulse='true';button.onanimationend=()=>delete button.dataset.pulse;setTimeout(()=>delete button.dataset.pulse,400)}else delete button.dataset.pulse;article.querySelector('.social-status').textContent=post.reaction===null?'Đã gỡ lời đồng hành':'Đã gửi lời đồng hành'}buttons.forEach(item=>item.disabled=false)});article.querySelector('[data-save]').onclick=()=>{post.saved=!post.saved;render()};article.querySelector('[data-detail]')?.addEventListener('click',()=>navigate(post.id));article.querySelector('[data-comment]').onclick=()=>navigate(post.id);article.querySelectorAll('.social-photo').forEach(button=>button.addEventListener('click',()=>viewer(post,Number(button.dataset.media))))})}
function showDialog(html,cls='',onClosed){const trigger=document.activeElement;const dialog=document.createElement('dialog');dialog.className=cls;dialog.setAttribute('aria-labelledby','prototype-dialog-title');dialog.innerHTML=html;document.body.append(dialog);dialog.addEventListener('close',()=>{dialog.remove();onClosed?.();const target=trigger?.id?document.getElementById(trigger.id):trigger;if(target?.isConnected)target.focus()});dialog.showModal();return dialog}
function viewer(post,index=0){const media=mediaFor(post);const dialog=showDialog(`<h2 id="prototype-dialog-title">Ảnh được chia sẻ <span id="viewer-position"></span></h2><img id="viewer-image" alt="Ảnh đầy đủ, không cắt"><div class="social-actions">${media.length>1?'<button id="previous-image">← Trước</button><button id="next-image">Tiếp →</button>':''}<button id="close-viewer">Đóng trình xem</button></div>`,'social-viewer');function update(){dialog.querySelector('#viewer-image').src=media[index];dialog.querySelector('#viewer-position').textContent=`${index+1}/${media.length}`}function move(delta){index=(index+delta+media.length)%media.length;update()}dialog.querySelector('#previous-image')?.addEventListener('click',()=>move(-1));dialog.querySelector('#next-image')?.addEventListener('click',()=>move(1));dialog.onkeydown=event=>{if(event.key==='ArrowLeft'||event.key==='ArrowRight'){event.preventDefault();move(event.key==='ArrowLeft'?-1:1)}};dialog.querySelector('#close-viewer').onclick=()=>dialog.close();update()}
function compose(){const dialog=showDialog(`<h2 id="prototype-dialog-title">Tạo bài viết</h2><label for="post-draft">Nội dung chia sẻ</label><textarea id="post-draft" rows="5">${escapeText(draft)}</textarea><p class="social-meta">Dùng danh tính cộng đồng · Câu chuyện của tôi</p><p id="compose-status" role="status"></p><div class="social-actions"><button id="keep-draft">Để sau</button><button id="publish-post" class="social-primary">Đăng bài</button></div>`,'',render);const input=dialog.querySelector('textarea');input.focus();input.oninput=()=>{draft=input.value};dialog.querySelector('#keep-draft').onclick=()=>{draft=input.value;dialog.close()};dialog.querySelector('#publish-post').onclick=()=>{if(!input.value.trim()||[...input.value.trim()].length>5000){const status=dialog.querySelector('#compose-status');status.setAttribute('role','alert');status.textContent=input.value.trim()?'Rút gọn nội dung còn tối đa 5.000 ký tự.':'Viết nội dung trước khi đăng.';input.focus();return}const post={id:`new${posts.length}`,name:profileName,text:input.value.trim(),topics:[0],image:false,count:0,reaction:null,saved:false,comments:[]};posts.unshift(post);draft='';dialog.close();navigate(post.id)}}
function navigate(view){current=view;render();window.scrollTo(0,0);document.querySelectorAll('.community-header-tabs a,.community-mobile-nav a').forEach(link=>{const active=(view==='feed'||posts.some(post=>post.id===view))?link.pathname==='/community':link.pathname.endsWith('/'+view);link.classList.toggle('is-active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')})}
document.querySelectorAll('a[href^="/community"]').forEach(link=>link.onclick=event=>{event.preventDefault();navigate(link.pathname.endsWith('/saved')?'saved':link.pathname.endsWith('/profile')?'profile':'feed')})
document.querySelector('#simulate-error').onclick=()=>{failNext=true;document.querySelector('#simulate-error').textContent='Thao tác kế tiếp sẽ báo lỗi'}
render()
function mediaFor(post){return post.image?(post.gallery?[photo,landscape]:[photo]):[]}
function renderTopics(post){return (post.topics??[0]).map(index=>`<span>${topics[index]}</span>`).join('')}
function renderMedia(post){const media=mediaFor(post);return media.length?`<div class="social-gallery ${media.length>1?'is-multiple':'is-single'}">${media.map((url,index)=>`<button class="social-photo" data-media="${index}" aria-label="Mở ảnh ${index+1} trên ${media.length}"><img src="${url}" alt="${index===0?'Một góc nghỉ ngơi bình yên':'Khoảng trời rộng và những dãy núi'}"></button>`).join('')}</div>`:''}
function emptyState(saved){return `<section class="community-state" role="status"><h2>${saved?'Bạn chưa lưu bài viết nào':'Chưa có bài viết trong chủ đề này'}</h2><p>${saved?'Chọn Lưu bài khi gặp một câu chuyện muốn đọc lại.':'Chọn chủ đề khác hoặc Tất cả để tiếp tục khám phá.'}</p></section>`}
